BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"ui-ux-design","task_number":1,"title":"User Interview Plan","old_description":"[[AZ]]\nİntern portalında tələbələrin tapşırıq axtarışı və təhvil vermə ehtiyacını öyrənmək üçün müsahibə planı hazırla.\n\n[[EN]]\nPrepare an interview plan to understand how students find and submit tasks in an intern portal.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTələbələrin tapşırığı tapmaq, tələbi anlamaq və həllini təqdim etmək zamanı yaşadığı çətinlikləri öyrənmək üçün müsahibə planı hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nİstifadəçi araşdırmasının məqsədi, açıq sualların üstünlüyü və Figma/Penpot-da sadə sənəd hazırlamaq. Razılıq olmadan qeyd aparma və lazımsız şəxsi məlumat toplama.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `student-task-research` repo-su yarat. Sıfırdan başla.\n2. `README.md`, `interview-guide.md` və `findings.md` faylları yarat.\n3. Araşdırma sualını yaz: “Tələbələr tapşırığın şərtini anlamaqda və həll linkini təqdim etməkdə hansı çətinliklərlə qarşılaşır?”\n4. 8–10 açıq sual yaz. Məsələn: “Son dəfə onlayn tapşırıq təqdim edəndə hansı addım çətin oldu?” Cavabı təlqin edən suallardan qaç.\n5. İştirakçıya məqsədi izah edən razılıq mətni hazırla; ad, telefon və başqa lazımsız məlumat toplama.\n6. Mümkündürsə, bir nəfərlə 15–20 dəqiqəlik sınaq müsahibəsi et. İştirakçı yoxdursa, simulyasiyanı real müsahibə kimi göstərmə.\n7. 3 müşahidə, 2 fərziyyə və növbəti addımı `findings.md`-də yaz, sonra repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nYönləndirən “Tapşırıq düyməsi sizi çaşdırır?” əvəzinə “Son dəfə tapşırıq təqdim edəndə nə etdiniz?” soruş. Müşahidə iştirakçının həqiqətən dediyi/etdiyidir; fərziyyə hələ yoxlamadığın izahdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 8–10 suallı müsahibə planı, razılıq mətni, anonim qeydlər və 3 müşahidə ilə araşdırma məhdudiyyətləri.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n8–10 açıq sual, razılıq mətni və müsahibə üsulu var. Real iştirakçı yoxdursa nəticələr simulyasiya kimi işarələnib; şəxsi məlumat yerinə anonim qeyd istifadə olunub.\n\n[[EN]]\n## 1. Goal\nPrepare an interview plan to learn what makes it difficult for students to find a task, understand its requirements, and submit a solution.\n\n## 2. Before you start\nThe purpose of user research, why open-ended questions help, and how to create a simple document in Figma/Penpot. Do not record without consent or collect unnecessary personal data.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `student-task-research`. Start from scratch.\n2. Create `README.md`, `interview-guide.md`, and `findings.md`.\n3. Write the research question: “What difficulties do students face when understanding task instructions and submitting a solution link?”\n4. Write 8–10 open questions. For example: “Which step was difficult the last time you submitted an online task?” Avoid leading questions.\n5. Prepare a consent statement explaining the purpose. Do not collect names, phone numbers, or other unnecessary information.\n6. If possible, run a 15–20 minute pilot interview. If no participant is available, do not present a simulation as a real interview.\n7. Record three observations, two assumptions, and a next step in `findings.md`, then push the repository to GitHub.\n\n## 4. Concrete example and explanation\nInstead of leading “Does the task button confuse you?”, ask “What did you do the last time you submitted a task?” An observation records what happened; an assumption is an unverified explanation.\n\n## 5. What to submit\nYour own GitHub repository link, an interview guide with 8–10 questions, consent statement, anonymized notes, three observations, and research limitations.\n\n## 6. How to check your work\nInclude 8–10 open questions, consent text, and interview method. Label simulations when no participant is available and use anonymous notes.","new_description":"[[AZ]]\nİntern portalında tələbələrin tapşırıq axtarışı və təhvil vermə ehtiyacını öyrənmək üçün müsahibə planı hazırla.\n\nPulsuz alətlər: Penpot (free/open source), Google Docs (personal), GitHub Free. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nPrepare an interview plan to understand how students find and submit tasks in an intern portal.\n\nFree tools: Penpot (free/open source), Google Docs (personal), GitHub Free. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Tələbənin tapşırığı tapmaqda çətinlik yaşamasını öyrənmək üçün 8 açıq müsahibə sualı yaz.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-1` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Araşdırma məqsədini və iştirakçı üçün razılıq mətni yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. 'Son dəfə tapşırıq göndərəndə nə etdiniz?' tipli açıq suallar qur. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Real iştirakçı yoxdursa sintetik cavabı 'simulyasiya' kimi ayır və 3 tapıntı çıxar. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Tələbənin tapşırığı tapmaqda çətinlik yaşamasını öyrənmək üçün 8 açıq müsahibə sualı yaz. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTələbənin tapşırığı tapmaqda çətinlik yaşamasını öyrənmək üçün 8 açıq müsahibə sualı yaz.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTələbələrin tapşırığı tapmaq, tələbi anlamaq və həllini təqdim etmək zamanı yaşadığı çətinlikləri öyrənmək üçün müsahibə planı hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nİstifadəçi araşdırmasının məqsədi, açıq sualların üstünlüyü və Figma/Penpot-da sadə sənəd hazırlamaq. Razılıq olmadan qeyd aparma və lazımsız şəxsi məlumat toplama.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `student-task-research` repo-su yarat. Sıfırdan başla.\n2. `README.md`, `interview-guide.md` və `findings.md` faylları yarat.\n3. Araşdırma sualını yaz: “Tələbələr tapşırığın şərtini anlamaqda və həll linkini təqdim etməkdə hansı çətinliklərlə qarşılaşır?”\n4. 8–10 açıq sual yaz. Məsələn: “Son dəfə onlayn tapşırıq təqdim edəndə hansı addım çətin oldu?” Cavabı təlqin edən suallardan qaç.\n5. İştirakçıya məqsədi izah edən razılıq mətni hazırla; ad, telefon və başqa lazımsız məlumat toplama.\n6. Mümkündürsə, bir nəfərlə 15–20 dəqiqəlik sınaq müsahibəsi et. İştirakçı yoxdursa, simulyasiyanı real müsahibə kimi göstərmə.\n7. 3 müşahidə, 2 fərziyyə və növbəti addımı `findings.md`-də yaz, sonra repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nYönləndirən “Tapşırıq düyməsi sizi çaşdırır?” əvəzinə “Son dəfə tapşırıq təqdim edəndə nə etdiniz?” soruş. Müşahidə iştirakçının həqiqətən dediyi/etdiyidir; fərziyyə hələ yoxlamadığın izahdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 8–10 suallı müsahibə planı, razılıq mətni, anonim qeydlər və 3 müşahidə ilə araşdırma məhdudiyyətləri.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n8–10 açıq sual, razılıq mətni və müsahibə üsulu var. Real iştirakçı yoxdursa nəticələr simulyasiya kimi işarələnib; şəxsi məlumat yerinə anonim qeyd istifadə olunub.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Draft eight open-ended questions about challenges finding and submitting tasks.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-1` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Define the research objective and a consent statement. Show evidence in a real screen, prototype, source file or test.\n4. Use neutral prompts such as 'What did you do last time you submitted a task?'. Show evidence in a real screen, prototype, source file or test.\n5. If no participants consent, label fictional answers as simulations and document three findings. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Draft eight open-ended questions about challenges finding and submitting tasks. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nDraft eight open-ended questions about challenges finding and submitting tasks.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nPrepare an interview plan to learn what makes it difficult for students to find a task, understand its requirements, and submit a solution.\n\n## 2. Before you start\nThe purpose of user research, why open-ended questions help, and how to create a simple document in Figma/Penpot. Do not record without consent or collect unnecessary personal data.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `student-task-research`. Start from scratch.\n2. Create `README.md`, `interview-guide.md`, and `findings.md`.\n3. Write the research question: “What difficulties do students face when understanding task instructions and submitting a solution link?”\n4. Write 8–10 open questions. For example: “Which step was difficult the last time you submitted an online task?” Avoid leading questions.\n5. Prepare a consent statement explaining the purpose. Do not collect names, phone numbers, or other unnecessary information.\n6. If possible, run a 15–20 minute pilot interview. If no participant is available, do not present a simulation as a real interview.\n7. Record three observations, two assumptions, and a next step in `findings.md`, then push the repository to GitHub.\n\n## 4. Concrete example and explanation\nInstead of leading “Does the task button confuse you?”, ask “What did you do the last time you submitted a task?” An observation records what happened; an assumption is an unverified explanation.\n\n## 5. What to submit\nYour own GitHub repository link, an interview guide with 8–10 questions, consent statement, anonymized notes, three observations, and research limitations.\n\n## 6. How to check your work\nInclude 8–10 open questions, consent text, and interview method. Label simulations when no participant is available and use anonymous notes."},{"slug":"ui-ux-design","task_number":2,"title":"User Flow","old_description":"[[AZ]]\nMüsahibə tapıntılarından tapşırıq tapma və təqdim etmə üçün əsas user flow və edge case-lər qur.\n\n[[EN]]\nTurn interview findings into a primary task-discovery/submission user flow and edge cases.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTələbənin tapşırığı tapmaqdan həllini təqdim etməyə qədər keçdiyi addımları user-flow diaqramında göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki araşdırma qeydlərin və ya açıq şəkildə qeyd etdiyin fərziyyələr. Figma, FigJam və ya Penpot kimi diaqram aləti kifayətdir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-in araşdırma faylını və öz dizayn faylını davam etdir.\n2. Əsas istifadəçi məqsədini və başlanğıc nöqtəsini yaz.\n3. Dashboard → task list → task detail → solution submission axınını çək.\n4. Task bağlıdırsa, məlumat yanlışdırsa və ya təqdimetmə uğursuz olarsa alternativ yollar əlavə et.\n5. Hər addımda istifadəçinin nə etdiyini və sistemin necə cavab verdiyini qeyd et.\n6. Diaqramı başqa tələbəyə göstər və anlaşılmayan hissələri düzəlt.\n\n## 4. Konkret nümunə və izah\nUser flow istifadəçinin addım və qərar yollarının sxemidir: siyahı → detal → həll linki → yoxlama → uğur. “Link düzgün deyil” qərarı istifadəçini sahəyə qaytarsın; “tapşırıq bağlıdır” yolunun da aydın sonu olsun.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn/diaqram linki, əsas axın və ən azı 3 xəta/alternativ axın, fərziyyə və qərar qeydləri. Hər yolun başlanğıcı və sonu aydın olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏsas yol və 3 alternativ yolun başlanğıcı/sonu görünür. İstifadəçi hərəkəti ilə sistem cavabı ayrılıb; fərziyyələr ayrıca qeydə alınıb.\n\n[[EN]]\n## 1. Goal\nMap the steps a student takes from finding a task to submitting a solution.\n\n## 2. Before you start\nYour Task 1 research notes or clearly labelled assumptions. Use a diagramming tool such as Figma, FigJam, or Penpot.\n\n## 3. Step-by-step work\n1. Continue your Task 1 research file and your own design file.\n2. State the user's main goal and starting point.\n3. Map dashboard → task list → task detail → solution submission.\n4. Add alternate paths for a closed task, invalid information, or failed submission.\n5. Show what the user does and how the system responds at each step.\n6. Ask another student to review the diagram and fix unclear parts.\n\n## 4. Concrete example and explanation\nA user flow maps actions and decisions: list → detail → solution URL → validation → success. Invalid URLs return to the field, while a closed task has its own clear outcome.\n\n## 5. What to submit\nA shareable design/diagram link, the main flow, at least three error/alternate flows, and notes on assumptions and decisions. Every path must have a clear start and end.\n\n## 6. How to check your work\nShow the main path and three alternatives with starts/ends. Distinguish user actions from system responses and label assumptions.","new_description":"[[AZ]]\nMüsahibə tapıntılarından tapşırıq tapma və təqdim etmə üçün əsas user flow və edge case-lər qur.\n\nPulsuz alətlər: diagrams.net, Penpot (free/open source). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nTurn interview findings into a primary task-discovery/submission user flow and edge cases.\n\nFree tools: diagrams.net, Penpot (free/open source). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Task siyahısı → detal → fayl yüklə → təsdiq axınını oxlarla göstər, xəta qolları əlavə et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **diagrams.net** — https://app.diagrams.net. Blank diagram seç, addımları oxlarla birləşdir və PNG/PDF çıxart.\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-2` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Start/end, seçim və error vəziyyətlərini flowchart-da ayır. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Ən azı 7 addımlı əsas axın və 2 alternativ hal qur. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Mümkün geri dönüşləri və istifadəçinin hansı məlumatı gördüyünü qeyd et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Task siyahısı → detal → fayl yüklə → təsdiq axınını oxlarla göstər, xəta qolları əlavə et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTask siyahısı → detal → fayl yüklə → təsdiq axınını oxlarla göstər, xəta qolları əlavə et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTələbənin tapşırığı tapmaqdan həllini təqdim etməyə qədər keçdiyi addımları user-flow diaqramında göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki araşdırma qeydlərin və ya açıq şəkildə qeyd etdiyin fərziyyələr. Figma, FigJam və ya Penpot kimi diaqram aləti kifayətdir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-in araşdırma faylını və öz dizayn faylını davam etdir.\n2. Əsas istifadəçi məqsədini və başlanğıc nöqtəsini yaz.\n3. Dashboard → task list → task detail → solution submission axınını çək.\n4. Task bağlıdırsa, məlumat yanlışdırsa və ya təqdimetmə uğursuz olarsa alternativ yollar əlavə et.\n5. Hər addımda istifadəçinin nə etdiyini və sistemin necə cavab verdiyini qeyd et.\n6. Diaqramı başqa tələbəyə göstər və anlaşılmayan hissələri düzəlt.\n\n## 4. Konkret nümunə və izah\nUser flow istifadəçinin addım və qərar yollarının sxemidir: siyahı → detal → həll linki → yoxlama → uğur. “Link düzgün deyil” qərarı istifadəçini sahəyə qaytarsın; “tapşırıq bağlıdır” yolunun da aydın sonu olsun.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn/diaqram linki, əsas axın və ən azı 3 xəta/alternativ axın, fərziyyə və qərar qeydləri. Hər yolun başlanğıcı və sonu aydın olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏsas yol və 3 alternativ yolun başlanğıcı/sonu görünür. İstifadəçi hərəkəti ilə sistem cavabı ayrılıb; fərziyyələr ayrıca qeydə alınıb.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Map task list → detail → upload → confirmation with an error branch.\n\n## Free platforms and how to use them\n- **diagrams.net** — https://app.diagrams.net. Create a blank diagram, connect steps with arrows and export PNG/PDF.\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-2` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Mark start/end, decisions and failure states in a diagram. Show evidence in a real screen, prototype, source file or test.\n4. Include at least seven main steps and two alternative paths. Show evidence in a real screen, prototype, source file or test.\n5. Document navigation back paths and information available at each step. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Map task list → detail → upload → confirmation with an error branch. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nMap task list → detail → upload → confirmation with an error branch.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nMap the steps a student takes from finding a task to submitting a solution.\n\n## 2. Before you start\nYour Task 1 research notes or clearly labelled assumptions. Use a diagramming tool such as Figma, FigJam, or Penpot.\n\n## 3. Step-by-step work\n1. Continue your Task 1 research file and your own design file.\n2. State the user's main goal and starting point.\n3. Map dashboard → task list → task detail → solution submission.\n4. Add alternate paths for a closed task, invalid information, or failed submission.\n5. Show what the user does and how the system responds at each step.\n6. Ask another student to review the diagram and fix unclear parts.\n\n## 4. Concrete example and explanation\nA user flow maps actions and decisions: list → detail → solution URL → validation → success. Invalid URLs return to the field, while a closed task has its own clear outcome.\n\n## 5. What to submit\nA shareable design/diagram link, the main flow, at least three error/alternate flows, and notes on assumptions and decisions. Every path must have a clear start and end.\n\n## 6. How to check your work\nShow the main path and three alternatives with starts/ends. Distinguish user actions from system responses and label assumptions."},{"slug":"ui-ux-design","task_number":3,"title":"Low-Fidelity Wireframe","old_description":"[[AZ]]\nDashboard, tapşırıq detalı və submit axını üçün low-fidelity wireframe və layout qərarları hazırla.\n\n[[EN]]\nCreate low-fidelity wireframes for the dashboard, task detail, and submission flow.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nRəng və dekorasiyadan əvvəl ekranların quruluşunu, məlumat iyerarxiyasını və əsas düymələri yoxlayan sadə wireframe hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 2-dəki user-flow diaqramın. Figma/Penpot və ya kağız-qələm istifadə edə bilərsən; kod yazmaq tələb olunmur.\n\n## 3. Addım-addım icra\n1. Öz dizayn faylında Tapşırıq 2-ni davam etdir.\n2. Dashboard, task detail, solution submission və submission error üçün ən azı 4 ekran çək.\n3. Hər ekranda əsas başlıq, status, deadline və primary action-ı göstər.\n4. Desktop və mobil variant hazırla; loading, empty və error vəziyyətlərini ayrıca göstər.\n5. 3 istifadəçi ssenarisini yoxla: task tapmaq, təlimatı oxumaq, həll təqdim etmək.\n6. Rəy al və ən azı 3 dəyişiklik et.\n\n## 4. Konkret nümunə və izah\nWireframe rəngsiz və sadə ekran skeletidir; məqsəd dekorasiya yox, məlumatın yeridir. Ekranları 1–4 nömrələ, əsas düymənin hansı ekrana apardığını oxla göstər; həqiqi mətnə yaxın təlimat istifadə et.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn linki və ya PDF, ən azı 4 wireframe, mobil variant və 3 rəy/dəyişiklik qeydi. İstifadəçi növbəti addımı asanlıqla tapmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd əsas ekran və mobil uyğunlaşma görünür; loading, boş və xəta halları əsas ekran variantları kimi ayrıca işarələnib. Üç rəy və edilən dəyişiklik qeyd olunub.\n\n[[EN]]\n## 1. Goal\nCreate simple wireframes to test screen structure, information hierarchy, and primary actions before adding visual styling.\n\n## 2. Before you start\nYour user-flow diagram from Task 2. Use Figma/Penpot or paper and pencil; coding is not required.\n\n## 3. Step-by-step work\n1. Continue Task 2 in your own design file.\n2. Sketch at least four screens: dashboard, task detail, solution submission, and submission error.\n3. Show the main heading, status, deadline, and primary action on each screen.\n4. Create desktop and mobile versions, with separate loading, empty, and error states.\n5. Walk through three scenarios: find a task, read its instructions, and submit a solution.\n6. Gather feedback and make at least three changes.\n\n## 4. Concrete example and explanation\nA wireframe is a simple screen skeleton focused on information placement. Number screens 1–4, connect primary actions, and use realistic instructional text.\n\n## 5. What to submit\nA shareable design link or PDF, at least four wireframes, a mobile version, and three feedback/change notes. Users should be able to identify the next step easily.\n\n## 6. How to check your work\nShow four main screens and mobile adaptation, with labelled loading/empty/error variants. Record three feedback points and the resulting changes.","new_description":"[[AZ]]\nDashboard, tapşırıq detalı və submit axını üçün low-fidelity wireframe və layout qərarları hazırla.\n\nPulsuz alətlər: Penpot (free/open source), Figma Starter (free tier). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nCreate low-fidelity wireframes for the dashboard, task detail, and submission flow.\n\nFree tools: Penpot (free/open source), Figma Starter (free tier). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Dashboard, task detail və submit ekranlarını əvvəlcə boz sadə bloklarla 360px enində çək.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Figma Starter (free tier)** — https://www.figma.com. Starter Draft faylında frame və komponent qur, pulsuz plandakı fayl limitlərini nəzərə al.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-3` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Hər ekranda əsas başlıq, tapşırıq mətni və bir CTA yerləşdir. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Vizual dekorasiyadan əvvəl məzmun iyerarxiyası və spacing həll et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Fayl seçimi və validation error halını ayrıca frame kimi göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Dashboard, task detail və submit ekranlarını əvvəlcə boz sadə bloklarla 360px enində çək. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nDashboard, task detail və submit ekranlarını əvvəlcə boz sadə bloklarla 360px enində çək.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nRəng və dekorasiyadan əvvəl ekranların quruluşunu, məlumat iyerarxiyasını və əsas düymələri yoxlayan sadə wireframe hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 2-dəki user-flow diaqramın. Figma/Penpot və ya kağız-qələm istifadə edə bilərsən; kod yazmaq tələb olunmur.\n\n## 3. Addım-addım icra\n1. Öz dizayn faylında Tapşırıq 2-ni davam etdir.\n2. Dashboard, task detail, solution submission və submission error üçün ən azı 4 ekran çək.\n3. Hər ekranda əsas başlıq, status, deadline və primary action-ı göstər.\n4. Desktop və mobil variant hazırla; loading, empty və error vəziyyətlərini ayrıca göstər.\n5. 3 istifadəçi ssenarisini yoxla: task tapmaq, təlimatı oxumaq, həll təqdim etmək.\n6. Rəy al və ən azı 3 dəyişiklik et.\n\n## 4. Konkret nümunə və izah\nWireframe rəngsiz və sadə ekran skeletidir; məqsəd dekorasiya yox, məlumatın yeridir. Ekranları 1–4 nömrələ, əsas düymənin hansı ekrana apardığını oxla göstər; həqiqi mətnə yaxın təlimat istifadə et.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn linki və ya PDF, ən azı 4 wireframe, mobil variant və 3 rəy/dəyişiklik qeydi. İstifadəçi növbəti addımı asanlıqla tapmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd əsas ekran və mobil uyğunlaşma görünür; loading, boş və xəta halları əsas ekran variantları kimi ayrıca işarələnib. Üç rəy və edilən dəyişiklik qeyd olunub.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Create low-fidelity 360px mobile wireframes for dashboard, task detail and submission.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Figma Starter (free tier)** — https://www.figma.com. Use free Starter draft files and components while respecting usage limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-3` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Place a clear heading, task content and one primary CTA on each screen. Show evidence in a real screen, prototype, source file or test.\n4. Prioritize information structure and spacing before styling. Show evidence in a real screen, prototype, source file or test.\n5. Include separate file-selection and validation-error frames. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Create low-fidelity 360px mobile wireframes for dashboard, task detail and submission. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nCreate low-fidelity 360px mobile wireframes for dashboard, task detail and submission.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate simple wireframes to test screen structure, information hierarchy, and primary actions before adding visual styling.\n\n## 2. Before you start\nYour user-flow diagram from Task 2. Use Figma/Penpot or paper and pencil; coding is not required.\n\n## 3. Step-by-step work\n1. Continue Task 2 in your own design file.\n2. Sketch at least four screens: dashboard, task detail, solution submission, and submission error.\n3. Show the main heading, status, deadline, and primary action on each screen.\n4. Create desktop and mobile versions, with separate loading, empty, and error states.\n5. Walk through three scenarios: find a task, read its instructions, and submit a solution.\n6. Gather feedback and make at least three changes.\n\n## 4. Concrete example and explanation\nA wireframe is a simple screen skeleton focused on information placement. Number screens 1–4, connect primary actions, and use realistic instructional text.\n\n## 5. What to submit\nA shareable design link or PDF, at least four wireframes, a mobile version, and three feedback/change notes. Users should be able to identify the next step easily.\n\n## 6. How to check your work\nShow four main screens and mobile adaptation, with labelled loading/empty/error variants. Record three feedback points and the resulting changes."},{"slug":"ui-ux-design","task_number":4,"title":"High-Fidelity Screens","old_description":"[[AZ]]\nWireframe-i real məzmun, visual hierarchy və responsive variantları olan high-fidelity ekranlara çevir.\n\n[[EN]]\nTurn wireframes into high-fidelity screens with real content, visual hierarchy, and responsive variants.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWireframe-ləri ardıcıl rəng, şrift və komponentlərdən istifadə edən yüksək dəqiqlikli ekranlara çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki wireframe-lərin, əsas vizual iyerarxiya, kontrast və responsive dizayn anlayışları. Figma və ya Penpot istifadə et.\n\n## 3. Addım-addım icra\n1. Öz dizayn faylında əvvəlki tapşırıqları davam etdir.\n2. Rəng, şrift ölçüsü, spacing və grid qaydalarını müəyyən et.\n3. Dashboard, task detail və submission üçün ən azı 3 high-fidelity ekran hazırla.\n4. Mobil ölçüdə ən azı iki ekranı yoxla; boş və xəta vəziyyətlərini də əlavə et.\n5. Əsas və ikinci dərəcəli düymələri fərqləndir, focus vəziyyətini göstər.\n6. Dizayn qərarlarını qısa qeyddə izah et və paylaşım icazəsini yoxla.\n\n## 4. Konkret nümunə və izah\nYüksək dəqiqlikli ekran finala yaxın rəng, şrift və komponent göstərir. Məsələn, bütün primary düymələr eyni rəng və ölçü qaydası ilə işləsin; “Uğursuz” statusunda rənglə yanaşı mətn də olsun.\n\n## 5. Nə təhvil verməlisən?\nRedaktə edilə bilən dizayn linki, 3 yüksək dəqiqlikli ekran, 2 mobil/state variantı və rəng/şrift/spacing qərarları. Mətn və əsas düymələr asan oxunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nÜç əsas ekran və iki mobil/vəziyyət variantı var. Mətnlər oxunaqlıdır, əsas action görünür və paylaşılmış link mentor üçün açılır.\n\n[[EN]]\n## 1. Goal\nTurn your wireframes into polished screens with consistent colors, typography, and components.\n\n## 2. Before you start\nYour earlier wireframes, visual hierarchy, contrast, and responsive-design basics. Use Figma or Penpot.\n\n## 3. Step-by-step work\n1. Continue earlier tasks in your own design file.\n2. Define color, type scale, spacing, and grid rules.\n3. Create at least three high-fidelity screens: dashboard, task detail, and submission.\n4. Check at least two screens on mobile and include empty/error states.\n5. Distinguish primary and secondary buttons and show keyboard-focus states.\n6. Briefly explain design decisions and verify sharing permissions.\n\n## 4. Concrete example and explanation\nA high-fidelity screen uses near-final typography, colors, and components. Primary buttons share consistent rules, and a Failed state includes text as well as color.\n\n## 5. What to submit\nAn editable design link, three high-fidelity screens, two mobile/state variants, and notes explaining color/type/spacing decisions. Text and primary actions must be easy to read.\n\n## 6. How to check your work\nProvide three main screens plus two mobile/state variants. Text and primary actions are readable, and the shared link opens for a reviewer.","new_description":"[[AZ]]\nWireframe-i real məzmun, visual hierarchy və responsive variantları olan high-fidelity ekranlara çevir.\n\nPulsuz alətlər: Penpot (free/open source), Figma Starter (free tier). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nTurn wireframes into high-fidelity screens with real content, visual hierarchy, and responsive variants.\n\nFree tools: Penpot (free/open source), Figma Starter (free tier). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Əvvəlki 3 wireframe-ə rəng, şrift, ikon, real tapşırıq mətni və mobil responsive variant əlavə et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Figma Starter (free tier)** — https://www.figma.com. Starter Draft faylında frame və komponent qur, pulsuz plandakı fayl limitlərini nəzərə al.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-4` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Rəng palitrası, type scale və komponentləri sənədləşdir. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Normal, disabled və error vəziyyətlərini ekranlarda göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Oxunaqlıq və vizual ardıcıllıq üçün before/after müqayisə et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Əvvəlki 3 wireframe-ə rəng, şrift, ikon, real tapşırıq mətni və mobil responsive variant əlavə et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nƏvvəlki 3 wireframe-ə rəng, şrift, ikon, real tapşırıq mətni və mobil responsive variant əlavə et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nWireframe-ləri ardıcıl rəng, şrift və komponentlərdən istifadə edən yüksək dəqiqlikli ekranlara çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki wireframe-lərin, əsas vizual iyerarxiya, kontrast və responsive dizayn anlayışları. Figma və ya Penpot istifadə et.\n\n## 3. Addım-addım icra\n1. Öz dizayn faylında əvvəlki tapşırıqları davam etdir.\n2. Rəng, şrift ölçüsü, spacing və grid qaydalarını müəyyən et.\n3. Dashboard, task detail və submission üçün ən azı 3 high-fidelity ekran hazırla.\n4. Mobil ölçüdə ən azı iki ekranı yoxla; boş və xəta vəziyyətlərini də əlavə et.\n5. Əsas və ikinci dərəcəli düymələri fərqləndir, focus vəziyyətini göstər.\n6. Dizayn qərarlarını qısa qeyddə izah et və paylaşım icazəsini yoxla.\n\n## 4. Konkret nümunə və izah\nYüksək dəqiqlikli ekran finala yaxın rəng, şrift və komponent göstərir. Məsələn, bütün primary düymələr eyni rəng və ölçü qaydası ilə işləsin; “Uğursuz” statusunda rənglə yanaşı mətn də olsun.\n\n## 5. Nə təhvil verməlisən?\nRedaktə edilə bilən dizayn linki, 3 yüksək dəqiqlikli ekran, 2 mobil/state variantı və rəng/şrift/spacing qərarları. Mətn və əsas düymələr asan oxunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nÜç əsas ekran və iki mobil/vəziyyət variantı var. Mətnlər oxunaqlıdır, əsas action görünür və paylaşılmış link mentor üçün açılır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Turn three wireframes into readable high-fidelity screens with realistic fictional content.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Figma Starter (free tier)** — https://www.figma.com. Use free Starter draft files and components while respecting usage limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-4` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Define palette, type scale and reusable visual components. Show evidence in a real screen, prototype, source file or test.\n4. Render normal, disabled and error states on the screens. Show evidence in a real screen, prototype, source file or test.\n5. Compare readability and visual consistency before and after changes. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Turn three wireframes into readable high-fidelity screens with realistic fictional content. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nTurn three wireframes into readable high-fidelity screens with realistic fictional content.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nTurn your wireframes into polished screens with consistent colors, typography, and components.\n\n## 2. Before you start\nYour earlier wireframes, visual hierarchy, contrast, and responsive-design basics. Use Figma or Penpot.\n\n## 3. Step-by-step work\n1. Continue earlier tasks in your own design file.\n2. Define color, type scale, spacing, and grid rules.\n3. Create at least three high-fidelity screens: dashboard, task detail, and submission.\n4. Check at least two screens on mobile and include empty/error states.\n5. Distinguish primary and secondary buttons and show keyboard-focus states.\n6. Briefly explain design decisions and verify sharing permissions.\n\n## 4. Concrete example and explanation\nA high-fidelity screen uses near-final typography, colors, and components. Primary buttons share consistent rules, and a Failed state includes text as well as color.\n\n## 5. What to submit\nAn editable design link, three high-fidelity screens, two mobile/state variants, and notes explaining color/type/spacing decisions. Text and primary actions must be easy to read.\n\n## 6. How to check your work\nProvide three main screens plus two mobile/state variants. Text and primary actions are readable, and the shared link opens for a reviewer."},{"slug":"ui-ux-design","task_number":5,"title":"Design System","old_description":"[[AZ]]\nRəng, type, spacing və əsas component variantlarını token-larla ifadə edən kiçik design system qur.\n\n[[EN]]\nBuild a small design system with tokens for color, type, spacing, and component variants.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTəkrar istifadə edilən dizayn token-ları və komponentlər yaradaraq ekranlar arasında vizual ardıcıllıq təmin edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki ekranların, rəng/şrift/spacing əsasları və komponent variantları. Figma/Penpot kifayətdir.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Semantic rəng, typography, spacing və radius token-ları yarat.\n3. Button, status badge, input və card komponentlərini ən azı iki variantla hazırla.\n4. Normal, disabled, loading və error state-ləri göstər.\n5. Kontrastı yoxla və token/komponent istifadəsi üçün qısa do/don't qaydaları yaz.\n6. Bir token-u dəyişərək əlaqəli komponentlərin ardıcıl yeniləndiyini yoxla.\n\n## 4. Konkret nümunə və izah\nToken təkrar istifadə olunan dizayn dəyəridir: məsələn, `color.action.primary` bütün əsas düymələrə bağlanır. Variant komponentin halıdır: Button/normal və Button/disabled. Dörd ailə yarat: Button, Badge, Input, Card; hərəsinə ən azı iki uyğun variant əlavə et.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn linki, rəng/şrift/aralıq token-ları, Button/Badge/Input/Card komponent ailələri, hər ailə üçün ən azı iki uyğun variant (cəmi ən azı səkkiz variant), kontrast yoxlaması və qısa istifadə təlimatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd komponent ailəsi və ən azı səkkiz variant görünür. Bir bağlı token dəyişəndə uyğun nümunələr birlikdə yenilənir; kontrast və istifadə qeydləri əlavə olunub.\n\n[[EN]]\n## 1. Goal\nCreate reusable design tokens and components so screens remain visually consistent.\n\n## 2. Before you start\nYour existing screens, color/type/spacing basics, and component variants. Figma/Penpot is enough.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Create semantic color, typography, spacing, and radius tokens.\n3. Build Button, status badge, input, and card components with at least two variants each.\n4. Show normal, disabled, loading, and error states.\n5. Check contrast and write brief do/don't rules for using tokens/components.\n6. Change one token and verify that related components update consistently.\n\n## 4. Concrete example and explanation\nA token is a reusable design value, such as `color.action.primary` linked to primary buttons. A variant is a component state, such as normal/disabled. Build four families: Button, Badge, Input, Card, each with at least two relevant variants.\n\n## 5. What to submit\nA shared design file, color/type/spacing tokens, Button/Badge/Input/Card component families with at least two relevant variants each (at least eight variants total), contrast checks, and a short usage guide.\n\n## 6. How to check your work\nShow four component families and at least eight variants. Changing one linked token updates relevant examples; include contrast and usage notes.","new_description":"[[AZ]]\nRəng, type, spacing və əsas component variantlarını token-larla ifadə edən kiçik design system qur.\n\nPulsuz alətlər: Penpot (free/open source), Figma Starter (free tier), WebAIM Contrast Checker. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild a small design system with tokens for color, type, spacing, and component variants.\n\nFree tools: Penpot (free/open source), Figma Starter (free tier), WebAIM Contrast Checker. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Primary button, input, badge və spacing token-ları üçün kiçik design system hazırla.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Figma Starter (free tier)** — https://www.figma.com. Starter Draft faylında frame və komponent qur, pulsuz plandakı fayl limitlərini nəzərə al.\n- **WebAIM Contrast Checker** — https://webaim.org/resources/contrastchecker/. Rəng kodlarını daxil edib normal mətn üçün WCAG AA 4.5:1 kontrastını yoxla.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-5` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Rəng və 8px spacing token-ları müəyyən et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Komponentlərin hover, focus, disabled və error variantlarını yarat. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Normal mətn kontrastını 4.5:1 hədəfinə görə yoxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Primary button, input, badge və spacing token-ları üçün kiçik design system hazırla. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nPrimary button, input, badge və spacing token-ları üçün kiçik design system hazırla.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTəkrar istifadə edilən dizayn token-ları və komponentlər yaradaraq ekranlar arasında vizual ardıcıllıq təmin edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki ekranların, rəng/şrift/spacing əsasları və komponent variantları. Figma/Penpot kifayətdir.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Semantic rəng, typography, spacing və radius token-ları yarat.\n3. Button, status badge, input və card komponentlərini ən azı iki variantla hazırla.\n4. Normal, disabled, loading və error state-ləri göstər.\n5. Kontrastı yoxla və token/komponent istifadəsi üçün qısa do/don't qaydaları yaz.\n6. Bir token-u dəyişərək əlaqəli komponentlərin ardıcıl yeniləndiyini yoxla.\n\n## 4. Konkret nümunə və izah\nToken təkrar istifadə olunan dizayn dəyəridir: məsələn, `color.action.primary` bütün əsas düymələrə bağlanır. Variant komponentin halıdır: Button/normal və Button/disabled. Dörd ailə yarat: Button, Badge, Input, Card; hərəsinə ən azı iki uyğun variant əlavə et.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan dizayn linki, rəng/şrift/aralıq token-ları, Button/Badge/Input/Card komponent ailələri, hər ailə üçün ən azı iki uyğun variant (cəmi ən azı səkkiz variant), kontrast yoxlaması və qısa istifadə təlimatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd komponent ailəsi və ən azı səkkiz variant görünür. Bir bağlı token dəyişəndə uyğun nümunələr birlikdə yenilənir; kontrast və istifadə qeydləri əlavə olunub.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Create a mini design system with buttons, inputs, badges and spacing tokens.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Figma Starter (free tier)** — https://www.figma.com. Use free Starter draft files and components while respecting usage limits.\n- **WebAIM Contrast Checker** — https://webaim.org/resources/contrastchecker/. Enter colors and check the 4.5:1 WCAG AA ratio for normal text.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-5` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Define color and 8px spacing tokens. Show evidence in a real screen, prototype, source file or test.\n4. Build hover, focus, disabled and error variants. Show evidence in a real screen, prototype, source file or test.\n5. Verify normal-text contrast against a 4.5:1 target. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Create a mini design system with buttons, inputs, badges and spacing tokens. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nCreate a mini design system with buttons, inputs, badges and spacing tokens.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate reusable design tokens and components so screens remain visually consistent.\n\n## 2. Before you start\nYour existing screens, color/type/spacing basics, and component variants. Figma/Penpot is enough.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Create semantic color, typography, spacing, and radius tokens.\n3. Build Button, status badge, input, and card components with at least two variants each.\n4. Show normal, disabled, loading, and error states.\n5. Check contrast and write brief do/don't rules for using tokens/components.\n6. Change one token and verify that related components update consistently.\n\n## 4. Concrete example and explanation\nA token is a reusable design value, such as `color.action.primary` linked to primary buttons. A variant is a component state, such as normal/disabled. Build four families: Button, Badge, Input, Card, each with at least two relevant variants.\n\n## 5. What to submit\nA shared design file, color/type/spacing tokens, Button/Badge/Input/Card component families with at least two relevant variants each (at least eight variants total), contrast checks, and a short usage guide.\n\n## 6. How to check your work\nShow four component families and at least eight variants. Changing one linked token updates relevant examples; include contrast and usage notes."},{"slug":"ui-ux-design","task_number":6,"title":"Prototype Interaction","old_description":"[[AZ]]\nTapşırıq oxuma, status dəyişməsi və submit interaction-larını clickable prototype-da sına.\n\n[[EN]]\nTest task-reading, status-change, and submission interactions in a clickable prototype.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nStatik ekranları kliklənən prototipə çevirib istifadəçinin əsas axını başa düşüb-düşmədiyini yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz dizayn sistemi və yüksək dəqiqlikli ekranların. Figma/Penpot prototip funksiyası kifayətdir.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Dashboard-dan task detail-ə, sonra submission ekranına keçidləri bağla.\n3. Submit üçün loading, success və error; həmçinin back/cancel/retry yollarını əlavə et.\n4. Ən azı 3 ssenari üzrə klikləri yoxla.\n5. Bir nəfərdən prototipi izahsız istifadə etməsini istə və ilişdiyi addımları qeyd et.\n6. Qeydlərə əsasən ən azı bir düzəliş et.\n\n## 4. Konkret nümunə və izah\nKliklənən prototipdə düymələr ekranları əlaqələndirir; backend qurulmur. Göndər düyməsi loading → success göstərə bilər; ayrıca simulyasiya yolu error → retry keçidini göstərsin.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan clickable prototype, 3 ssenari, success/error screenshot-ları və testdən sonra etdiyin düzəlişin izahı. Əsas CTA-lar işləyən növbəti addıma aparmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏsas keçidlər, back/cancel və retry çıxışları işləyir. Üç ssenari izlənə bilir; müşahidə əsasında ən azı bir düzəliş sənədləşib.\n\n[[EN]]\n## 1. Goal\nTurn static screens into a clickable prototype and check whether users understand the main flow.\n\n## 2. Before you start\nYour design system and high-fidelity screens. Figma/Penpot prototyping features are enough.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Connect dashboard → task detail → submission.\n3. Add loading, success, and error states for submit, plus back/cancel/retry paths.\n4. Test clicks across at least three scenarios.\n5. Ask one person to use the prototype without guidance and note where they get stuck.\n6. Make at least one change based on the feedback.\n\n## 4. Concrete example and explanation\nA clickable prototype links screens without requiring a backend. Submit can lead through loading → success, while a separate simulated branch shows error → retry.\n\n## 5. What to submit\nA shareable clickable prototype, three scenarios, success/error screenshots, and an explanation of a change made after testing. Primary actions must lead to a working next step.\n\n## 6. How to check your work\nPrimary navigation, back/cancel, and retry routes work. Follow three scenarios and document at least one observation-driven change.","new_description":"[[AZ]]\nTapşırıq oxuma, status dəyişməsi və submit interaction-larını clickable prototype-da sına.\n\nPulsuz alətlər: Penpot (free/open source), Figma Starter (free tier). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nTest task-reading, status-change, and submission interactions in a clickable prototype.\n\nFree tools: Penpot (free/open source), Figma Starter (free tier). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Tapşırıq siyahısında item aç, submit formuna keç və təsdiq mesajını clickable prototype-da göstər.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Figma Starter (free tier)** — https://www.figma.com. Starter Draft faylında frame və komponent qur, pulsuz plandakı fayl limitlərini nəzərə al.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-6` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Frame-lər arasında klik və back bağlantıları yarat. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Əsas 4 interaksiyanı success/error halları ilə göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. İstifadəçiyə əlavə söz izahı olmadan axını tamamlamağa çalış. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Tapşırıq siyahısında item aç, submit formuna keç və təsdiq mesajını clickable prototype-da göstər. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTapşırıq siyahısında item aç, submit formuna keç və təsdiq mesajını clickable prototype-da göstər.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nStatik ekranları kliklənən prototipə çevirib istifadəçinin əsas axını başa düşüb-düşmədiyini yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz dizayn sistemi və yüksək dəqiqlikli ekranların. Figma/Penpot prototip funksiyası kifayətdir.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Dashboard-dan task detail-ə, sonra submission ekranına keçidləri bağla.\n3. Submit üçün loading, success və error; həmçinin back/cancel/retry yollarını əlavə et.\n4. Ən azı 3 ssenari üzrə klikləri yoxla.\n5. Bir nəfərdən prototipi izahsız istifadə etməsini istə və ilişdiyi addımları qeyd et.\n6. Qeydlərə əsasən ən azı bir düzəliş et.\n\n## 4. Konkret nümunə və izah\nKliklənən prototipdə düymələr ekranları əlaqələndirir; backend qurulmur. Göndər düyməsi loading → success göstərə bilər; ayrıca simulyasiya yolu error → retry keçidini göstərsin.\n\n## 5. Nə təhvil verməlisən?\nPaylaşılan clickable prototype, 3 ssenari, success/error screenshot-ları və testdən sonra etdiyin düzəlişin izahı. Əsas CTA-lar işləyən növbəti addıma aparmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nƏsas keçidlər, back/cancel və retry çıxışları işləyir. Üç ssenari izlənə bilir; müşahidə əsasında ən azı bir düzəliş sənədləşib.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Build a clickable prototype from task list to submission confirmation.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Figma Starter (free tier)** — https://www.figma.com. Use free Starter draft files and components while respecting usage limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-6` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Connect frames with click and back interactions. Show evidence in a real screen, prototype, source file or test.\n4. Demonstrate four interactions including success and error states. Show evidence in a real screen, prototype, source file or test.\n5. Test whether the flow is understandable without narration. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Build a clickable prototype from task list to submission confirmation. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nBuild a clickable prototype from task list to submission confirmation.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nTurn static screens into a clickable prototype and check whether users understand the main flow.\n\n## 2. Before you start\nYour design system and high-fidelity screens. Figma/Penpot prototyping features are enough.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Connect dashboard → task detail → submission.\n3. Add loading, success, and error states for submit, plus back/cancel/retry paths.\n4. Test clicks across at least three scenarios.\n5. Ask one person to use the prototype without guidance and note where they get stuck.\n6. Make at least one change based on the feedback.\n\n## 4. Concrete example and explanation\nA clickable prototype links screens without requiring a backend. Submit can lead through loading → success, while a separate simulated branch shows error → retry.\n\n## 5. What to submit\nA shareable clickable prototype, three scenarios, success/error screenshots, and an explanation of a change made after testing. Primary actions must lead to a working next step.\n\n## 6. How to check your work\nPrimary navigation, back/cancel, and retry routes work. Follow three scenarios and document at least one observation-driven change."},{"slug":"ui-ux-design","task_number":7,"title":"Accessibility Review","old_description":"[[AZ]]\nTask detail prototipində keyboard, screen reader, kontrast və mətn böyütmə baryerlərini audit et.\n\n[[EN]]\nAudit keyboard, screen-reader, contrast, and text-scaling barriers in a task-detail prototype.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nDizaynın müxtəlif istifadə ehtiyacları üçün əlçatanlığını yoxlayıb problemlərə düzəliş təklif edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz task-list/detail və submission prototipin, kontrast, keyboard focus və form error anlayışları. WCAG 2.2 AA-nı yoxlama siyahısı kimi istifadə et; avtomatik sertifikat kimi təqdim etmə.\n\n## 3. Addım-addım icra\n1. Öz prototipinin əsas ekranlarını və istifadəçinin hansı məlumatı anlamalı olduğunu siyahıya al.\n2. Mətn/fon kontrastını alətlə ölç: adi mətn üçün ən azı 4.5:1, böyük mətn üçün 3:1 nisbətini yoxla; nəticəni qeyd et.\n3. Dizaynda nəzərdə tutulan fokus sırasını nömrələ, görünən fokus halı və form label/error əlaqəsi üçün annotasiya əlavə et.\n4. 200% böyüdülmüş görünüşdə uzun mətn və form sahələrini nəzərdən keçir. Status və xətanı rənglə yanaşı mətnlə də göstər.\n5. Ən azı 5 tapıntını yer, sübut, təsir və düzəlişlə yaz. Kodlanmış səhifə yoxdursa, klaviatura və screen reader maddələrini tətbiq mərhələsində yoxlanmalı kimi işarələ.\n6. Ən yüksək təsirli bir problemi düzəlt; eyni ölçüdə əvvəl/sonra nəticəni göstər.\n\n## 4. Konkret nümunə və izah\nFigma/Penpot dizaynında nəzərdə tutulan Tab sırasını nömrələ və focus görünüşünü çək. Həqiqi klaviatura və screen reader davranışını yalnız kodlanmış səhifədə yoxlamaq olar; dizayn prototipində bu maddələri “tətbiqdə yoxlanmalıdır” kimi qeyd et.\n\n## 5. Nə təhvil verməlisən?\nAccessibility checklist, 5+ tapıntı və düzəliş təklifi, sübut screenshot-ları və yenilənmiş prototip. Avtomatik scan yeganə yoxlama üsulu olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n5 tapıntıda sübut, təsir və təklif var. Dizaynda yoxlanan kontrast/mətnlə tətbiq tələb edən yoxlamalar ayrıdır; bir yüksək təsirli problem düzəldilib.\n\n[[EN]]\n## 1. Goal\nReview accessibility and recommend fixes for users with different access needs.\n\n## 2. Before you start\nYour task-list/detail and submission prototype, contrast, keyboard focus, and form-error basics. Use WCAG 2.2 AA as a checklist, not as an automatic compliance certificate.\n\n## 3. Step-by-step work\n1. List the main prototype screens and the information users need to understand.\n2. Measure text/background contrast with a tool: check at least 4.5:1 for ordinary text and 3:1 for large text, and record results.\n3. Annotate intended focus order, visible focus styles, and label/error relationships in the design.\n4. Review long text and fields at 200% magnification. Convey errors/status with text as well as color.\n5. Record at least five findings with location, evidence, impact, and fix. Without an implemented page, mark keyboard and screen-reader checks as requiring implementation verification.\n6. Fix one high-impact problem and show comparable before/after results.\n\n## 4. Concrete example and explanation\nIn a design file, annotate intended Tab order and draw focus styles. Actual keyboard and screen-reader behavior requires an implemented page; mark those checks as needing implementation verification.\n\n## 5. What to submit\nAn accessibility checklist, five or more findings and suggested fixes, evidence screenshots, and an updated prototype. Automated scanning must not be the only review method.\n\n## 6. How to check your work\nFor five findings include evidence, impact, and recommendation. Separate design checks from implementation checks and fix one high-impact issue.","new_description":"[[AZ]]\nTask detail prototipində keyboard, screen reader, kontrast və mətn böyütmə baryerlərini audit et.\n\nPulsuz alətlər: WebAIM Contrast Checker, Penpot (free/open source), Google Docs (personal). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nAudit keyboard, screen-reader, contrast, and text-scaling barriers in a task-detail prototype.\n\nFree tools: WebAIM Contrast Checker, Penpot (free/open source), Google Docs (personal). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Task detail ekranında font, kontrast, fokus sırası və alt text çatışmazlıqlarını audit et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **WebAIM Contrast Checker** — https://webaim.org/resources/contrastchecker/. Rəng kodlarını daxil edib normal mətn üçün WCAG AA 4.5:1 kontrastını yoxla.\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-7` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Siyahı, forma və düymələr üçün 5 bəndlik audit yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Kontrast ölçüsünü və klaviatura/fokus ardıcıllığını ayrıca qeyd et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Problemləri severity-yə görə sırala, düzəliş variantını göstərəndə sübut əlavə et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Task detail ekranında font, kontrast, fokus sırası və alt text çatışmazlıqlarını audit et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTask detail ekranında font, kontrast, fokus sırası və alt text çatışmazlıqlarını audit et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nDizaynın müxtəlif istifadə ehtiyacları üçün əlçatanlığını yoxlayıb problemlərə düzəliş təklif edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz task-list/detail və submission prototipin, kontrast, keyboard focus və form error anlayışları. WCAG 2.2 AA-nı yoxlama siyahısı kimi istifadə et; avtomatik sertifikat kimi təqdim etmə.\n\n## 3. Addım-addım icra\n1. Öz prototipinin əsas ekranlarını və istifadəçinin hansı məlumatı anlamalı olduğunu siyahıya al.\n2. Mətn/fon kontrastını alətlə ölç: adi mətn üçün ən azı 4.5:1, böyük mətn üçün 3:1 nisbətini yoxla; nəticəni qeyd et.\n3. Dizaynda nəzərdə tutulan fokus sırasını nömrələ, görünən fokus halı və form label/error əlaqəsi üçün annotasiya əlavə et.\n4. 200% böyüdülmüş görünüşdə uzun mətn və form sahələrini nəzərdən keçir. Status və xətanı rənglə yanaşı mətnlə də göstər.\n5. Ən azı 5 tapıntını yer, sübut, təsir və düzəlişlə yaz. Kodlanmış səhifə yoxdursa, klaviatura və screen reader maddələrini tətbiq mərhələsində yoxlanmalı kimi işarələ.\n6. Ən yüksək təsirli bir problemi düzəlt; eyni ölçüdə əvvəl/sonra nəticəni göstər.\n\n## 4. Konkret nümunə və izah\nFigma/Penpot dizaynında nəzərdə tutulan Tab sırasını nömrələ və focus görünüşünü çək. Həqiqi klaviatura və screen reader davranışını yalnız kodlanmış səhifədə yoxlamaq olar; dizayn prototipində bu maddələri “tətbiqdə yoxlanmalıdır” kimi qeyd et.\n\n## 5. Nə təhvil verməlisən?\nAccessibility checklist, 5+ tapıntı və düzəliş təklifi, sübut screenshot-ları və yenilənmiş prototip. Avtomatik scan yeganə yoxlama üsulu olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n5 tapıntıda sübut, təsir və təklif var. Dizaynda yoxlanan kontrast/mətnlə tətbiq tələb edən yoxlamalar ayrıdır; bir yüksək təsirli problem düzəldilib.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Audit task-detail screens for contrast, focus order, readable text and image alternatives.\n\n## Free platforms and how to use them\n- **WebAIM Contrast Checker** — https://webaim.org/resources/contrastchecker/. Enter colors and check the 4.5:1 WCAG AA ratio for normal text.\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-7` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Audit five criteria across lists, forms and buttons. Show evidence in a real screen, prototype, source file or test.\n4. Record contrast checks and expected keyboard/focus order. Show evidence in a real screen, prototype, source file or test.\n5. Prioritize severity and show evidence for proposed fixes. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Audit task-detail screens for contrast, focus order, readable text and image alternatives. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nAudit task-detail screens for contrast, focus order, readable text and image alternatives.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nReview accessibility and recommend fixes for users with different access needs.\n\n## 2. Before you start\nYour task-list/detail and submission prototype, contrast, keyboard focus, and form-error basics. Use WCAG 2.2 AA as a checklist, not as an automatic compliance certificate.\n\n## 3. Step-by-step work\n1. List the main prototype screens and the information users need to understand.\n2. Measure text/background contrast with a tool: check at least 4.5:1 for ordinary text and 3:1 for large text, and record results.\n3. Annotate intended focus order, visible focus styles, and label/error relationships in the design.\n4. Review long text and fields at 200% magnification. Convey errors/status with text as well as color.\n5. Record at least five findings with location, evidence, impact, and fix. Without an implemented page, mark keyboard and screen-reader checks as requiring implementation verification.\n6. Fix one high-impact problem and show comparable before/after results.\n\n## 4. Concrete example and explanation\nIn a design file, annotate intended Tab order and draw focus styles. Actual keyboard and screen-reader behavior requires an implemented page; mark those checks as needing implementation verification.\n\n## 5. What to submit\nAn accessibility checklist, five or more findings and suggested fixes, evidence screenshots, and an updated prototype. Automated scanning must not be the only review method.\n\n## 6. How to check your work\nFor five findings include evidence, impact, and recommendation. Separate design checks from implementation checks and fix one high-impact issue."},{"slug":"ui-ux-design","task_number":8,"title":"Responsive Adaptation","old_description":"[[AZ]]\nEyni task axınını dar mobil, tablet və desktop enlərində yenidən yerləşdir və content prioritetini saxla.\n\n[[EN]]\nAdapt the same task flow across narrow mobile, tablet, and desktop while preserving content priorities.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTask detail və submission ekranlarını mobil, tablet və desktop ölçülərinə uyğunlaşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki prototipin, responsive layout və content priority anlayışları. 360px, 768px və 1280px ölçülərini sına.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Task detail və submission ekranlarını 360px, 768px və 1280px viewport üçün hazırla.\n3. Desktop sidebar/navigation-ın mobil variantını müəyyən et.\n4. Uzun təlimat, kod nümunəsi və submit düyməsinin davranışını yoxla.\n5. Hər ölçüdə horizontal scroll, kəsilən mətn və əlçatmaz CTA olub-olmadığını yoxla.\n6. Üç ölçüdən screenshot və breakpoint qərarlarının izahını əlavə et.\n\n## 4. Konkret nümunə və izah\nİki əsas ekran üçün 360, 768 və 1280px ölçüləri hazırlamaq ən azı 6 əsas frame deməkdir. Mobil ekranda sidebar yığcam menyuya çevrilə bilər; uzun kod bloku öz daxilində sürüşə bilər, amma bütün səhifə yana daşmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÜç viewport üçün ekranlar, breakpoint/navigation qeydi və hər ölçüdə yoxlama screenshot-u. Əsas funksiyalar mobil və desktop-da əlçatan qalmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAltı əsas frame eyni məzmunu və funksiyaları göstərir. Uzun təlimat, xəta mesajı və əsas düymə hər ölçüdə yoxlanıb; breakpoint qərarları izah olunub.\n\n[[EN]]\n## 1. Goal\nAdapt task-detail and submission screens for mobile, tablet, and desktop.\n\n## 2. Before you start\nYour existing prototype, responsive-layout concepts, and content prioritization. Test 360px, 768px, and 1280px viewports.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Prepare task-detail and submission screens at 360px, 768px, and 1280px.\n3. Define a mobile version of desktop navigation/sidebar.\n4. Check long instructions, code samples, and submit-button behavior.\n5. At each size, check for horizontal scrolling, clipped text, and inaccessible primary actions.\n6. Add screenshots for all three sizes and explain breakpoint decisions.\n\n## 4. Concrete example and explanation\nTwo main screens at 360, 768, and 1280px means at least six main frames. A sidebar may become a compact mobile menu; code can scroll within its block without the whole page overflowing.\n\n## 5. What to submit\nScreens for three viewports, a breakpoint/navigation note, and screenshots proving each size was checked. Core functions must remain accessible on mobile and desktop.\n\n## 6. How to check your work\nSix main frames preserve content and functionality. Check long instructions, errors, and the primary action at each size; explain breakpoints.","new_description":"[[AZ]]\nEyni task axınını dar mobil, tablet və desktop enlərində yenidən yerləşdir və content prioritetini saxla.\n\nPulsuz alətlər: Penpot (free/open source), Figma Starter (free tier). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nAdapt the same task flow across narrow mobile, tablet, and desktop while preserving content priorities.\n\nFree tools: Penpot (free/open source), Figma Starter (free tier). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** 360px mobil, 768px planşet və 1440px desktop task ekranını eyni məzmunla dizayn et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Figma Starter (free tier)** — https://www.figma.com. Starter Draft faylında frame və komponent qur, pulsuz plandakı fayl limitlərini nəzərə al.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-8` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Üç frame ölçüsü qur, mətni qısaltmadan iyerarxiyanı saxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Düymələri touch üçün rahat və məzmunu scroll üçün oxunaqlı saxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Uzun tapşırıq başlığı və boş status halı üçün responsive test et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: 360px mobil, 768px planşet və 1440px desktop task ekranını eyni məzmunla dizayn et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\n360px mobil, 768px planşet və 1440px desktop task ekranını eyni məzmunla dizayn et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTask detail və submission ekranlarını mobil, tablet və desktop ölçülərinə uyğunlaşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki prototipin, responsive layout və content priority anlayışları. 360px, 768px və 1280px ölçülərini sına.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et.\n2. Task detail və submission ekranlarını 360px, 768px və 1280px viewport üçün hazırla.\n3. Desktop sidebar/navigation-ın mobil variantını müəyyən et.\n4. Uzun təlimat, kod nümunəsi və submit düyməsinin davranışını yoxla.\n5. Hər ölçüdə horizontal scroll, kəsilən mətn və əlçatmaz CTA olub-olmadığını yoxla.\n6. Üç ölçüdən screenshot və breakpoint qərarlarının izahını əlavə et.\n\n## 4. Konkret nümunə və izah\nİki əsas ekran üçün 360, 768 və 1280px ölçüləri hazırlamaq ən azı 6 əsas frame deməkdir. Mobil ekranda sidebar yığcam menyuya çevrilə bilər; uzun kod bloku öz daxilində sürüşə bilər, amma bütün səhifə yana daşmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÜç viewport üçün ekranlar, breakpoint/navigation qeydi və hər ölçüdə yoxlama screenshot-u. Əsas funksiyalar mobil və desktop-da əlçatan qalmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAltı əsas frame eyni məzmunu və funksiyaları göstərir. Uzun təlimat, xəta mesajı və əsas düymə hər ölçüdə yoxlanıb; breakpoint qərarları izah olunub.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Adapt the same task content to 360px, 768px and 1440px layouts.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Figma Starter (free tier)** — https://www.figma.com. Use free Starter draft files and components while respecting usage limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-8` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Create three frames preserving the same content and hierarchy. Show evidence in a real screen, prototype, source file or test.\n4. Maintain comfortable touch targets and readable scrolling. Show evidence in a real screen, prototype, source file or test.\n5. Check long headings and empty states on all viewports. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Adapt the same task content to 360px, 768px and 1440px layouts. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nAdapt the same task content to 360px, 768px and 1440px layouts.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nAdapt task-detail and submission screens for mobile, tablet, and desktop.\n\n## 2. Before you start\nYour existing prototype, responsive-layout concepts, and content prioritization. Test 360px, 768px, and 1280px viewports.\n\n## 3. Step-by-step work\n1. Continue in the same design file.\n2. Prepare task-detail and submission screens at 360px, 768px, and 1280px.\n3. Define a mobile version of desktop navigation/sidebar.\n4. Check long instructions, code samples, and submit-button behavior.\n5. At each size, check for horizontal scrolling, clipped text, and inaccessible primary actions.\n6. Add screenshots for all three sizes and explain breakpoint decisions.\n\n## 4. Concrete example and explanation\nTwo main screens at 360, 768, and 1280px means at least six main frames. A sidebar may become a compact mobile menu; code can scroll within its block without the whole page overflowing.\n\n## 5. What to submit\nScreens for three viewports, a breakpoint/navigation note, and screenshots proving each size was checked. Core functions must remain accessible on mobile and desktop.\n\n## 6. How to check your work\nSix main frames preserve content and functionality. Check long instructions, errors, and the primary action at each size; explain breakpoints."},{"slug":"ui-ux-design","task_number":9,"title":"UX Usability Test","old_description":"[[AZ]]\nPrototipdə tapşırığı tapma və təqdim etmə usability testini apar, tapıntıları prioritetləşdir.\n\n[[EN]]\nRun a usability test on finding and submitting a task, then prioritize findings.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçilərin task list və detail axınını əlavə izah olmadan başa düşüb-düşmədiyini test edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz clickable prototipin və neytral test ssenarisi. Mümkünsə 3–5 iştirakçı ilə işlə; daha az iştirakçı varsa, sayını açıq göstər.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et və 2–3 konkret istifadəçi tapşırığı yaz.\n2. İştirakçıdan uyğun task-ı tapmağı, statusu anlamağı və həll formatını müəyyən etməyi istə.\n3. Cavabı yönləndirmə; vaxt, səhv klik və kömək istəklərini qeyd et.\n4. Razılıq al, qeydləri anonim saxla və lazımsız şəxsi məlumat toplama.\n5. Tapıntıları tezlik və təsirə görə sırala.\n6. Bir düzəliş et və mümkündürsə həmin ssenarini yenidən test et.\n\n## 4. Konkret nümunə və izah\nSsenari: “Sənə uyğun açıq tapşırığı tap və tələb olunan həll formatını müəyyən et”. Bitirmə vaxtını, yanlış klikləri və kömək istəklərini yaz. Problem tezliyi = neçə iştirakçıda görüldü / neçə iştirakçı test etdi.\n\n## 5. Nə təhvil verməlisən?\nTest planı, iştirakçı sayı, anonim müşahidə qeydləri, ən azı 5 tapıntı və severity/impact cədvəli, yenilənmiş prototip və retest nəticəsi. Kiçik nümunədən böyük nəticə çıxarma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİştirakçı sayı, razılıq və anonim qeydlər var. Beş müşahidə prioritetləşdirilib; real müşahidə azdırsa tapıntı uydurulmayıb, çatışmayanlar fərziyyə kimi qeyd edilib.\n\n[[EN]]\n## 1. Goal\nTest whether users can understand the task-list and detail flow without extra explanation.\n\n## 2. Before you start\nYour clickable prototype and neutral test scenarios. Aim for three to five participants; clearly state if fewer take part.\n\n## 3. Step-by-step work\n1. Continue in the same design file and write two or three concrete user tasks.\n2. Ask participants to find a suitable task, understand its status, and identify the required submission format.\n3. Do not lead their answers; record time, misclicks, and requests for help.\n4. Obtain consent, anonymize notes, and avoid unnecessary personal data.\n5. Rank findings by frequency and impact.\n6. Make one change and, if possible, retest the same scenario.\n\n## 4. Concrete example and explanation\nScenario: “Find an open task relevant to you and identify the required submission format.” Record completion time, wrong clicks, and help requests. Report issue frequency as affected participants / tested participants.\n\n## 5. What to submit\nA test plan, participant count, anonymized observations, at least five findings with severity/impact, updated prototype, and retest results. Do not overgeneralize from a small sample.\n\n## 6. How to check your work\nDocument participant count, consent, and anonymous notes. Prioritize five observations; do not invent findings when evidence is limited—label hypotheses separately.","new_description":"[[AZ]]\nPrototipdə tapşırığı tapma və təqdim etmə usability testini apar, tapıntıları prioritetləşdir.\n\nPulsuz alətlər: Google Docs (personal), Penpot (free/open source). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nRun a usability test on finding and submitting a task, then prioritize findings.\n\nFree tools: Google Docs (personal), Penpot (free/open source). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** 3 neytral tapşırıqla usability sınağı apar; real iştirakçı varsa razılıq al, yoxdursa mock qeyd et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-9` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Tapşırığı tapmaq və göndərmək üçün ölçülən test ssenariləri yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Harada dayanma/yanlış klik yarandığını qeyd et, ad-soyad toplama. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Ən vacib iki problemi düzəltmək üçün öncə/sonra prototip göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: 3 neytral tapşırıqla usability sınağı apar; real iştirakçı varsa razılıq al, yoxdursa mock qeyd et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\n3 neytral tapşırıqla usability sınağı apar; real iştirakçı varsa razılıq al, yoxdursa mock qeyd et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçilərin task list və detail axınını əlavə izah olmadan başa düşüb-düşmədiyini test edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz clickable prototipin və neytral test ssenarisi. Mümkünsə 3–5 iştirakçı ilə işlə; daha az iştirakçı varsa, sayını açıq göstər.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylında davam et və 2–3 konkret istifadəçi tapşırığı yaz.\n2. İştirakçıdan uyğun task-ı tapmağı, statusu anlamağı və həll formatını müəyyən etməyi istə.\n3. Cavabı yönləndirmə; vaxt, səhv klik və kömək istəklərini qeyd et.\n4. Razılıq al, qeydləri anonim saxla və lazımsız şəxsi məlumat toplama.\n5. Tapıntıları tezlik və təsirə görə sırala.\n6. Bir düzəliş et və mümkündürsə həmin ssenarini yenidən test et.\n\n## 4. Konkret nümunə və izah\nSsenari: “Sənə uyğun açıq tapşırığı tap və tələb olunan həll formatını müəyyən et”. Bitirmə vaxtını, yanlış klikləri və kömək istəklərini yaz. Problem tezliyi = neçə iştirakçıda görüldü / neçə iştirakçı test etdi.\n\n## 5. Nə təhvil verməlisən?\nTest planı, iştirakçı sayı, anonim müşahidə qeydləri, ən azı 5 tapıntı və severity/impact cədvəli, yenilənmiş prototip və retest nəticəsi. Kiçik nümunədən böyük nəticə çıxarma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİştirakçı sayı, razılıq və anonim qeydlər var. Beş müşahidə prioritetləşdirilib; real müşahidə azdırsa tapıntı uydurulmayıb, çatışmayanlar fərziyyə kimi qeyd edilib.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Run three neutral usability tasks with consent or mark a simulation honestly.\n\n## Free platforms and how to use them\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-9` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Write measurable find-and-submit usability tasks. Show evidence in a real screen, prototype, source file or test.\n4. Record confusion or wrong clicks without collecting identities. Show evidence in a real screen, prototype, source file or test.\n5. Prioritize two fixes and compare before/after prototype frames. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Run three neutral usability tasks with consent or mark a simulation honestly. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nRun three neutral usability tasks with consent or mark a simulation honestly.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nTest whether users can understand the task-list and detail flow without extra explanation.\n\n## 2. Before you start\nYour clickable prototype and neutral test scenarios. Aim for three to five participants; clearly state if fewer take part.\n\n## 3. Step-by-step work\n1. Continue in the same design file and write two or three concrete user tasks.\n2. Ask participants to find a suitable task, understand its status, and identify the required submission format.\n3. Do not lead their answers; record time, misclicks, and requests for help.\n4. Obtain consent, anonymize notes, and avoid unnecessary personal data.\n5. Rank findings by frequency and impact.\n6. Make one change and, if possible, retest the same scenario.\n\n## 4. Concrete example and explanation\nScenario: “Find an open task relevant to you and identify the required submission format.” Record completion time, wrong clicks, and help requests. Report issue frequency as affected participants / tested participants.\n\n## 5. What to submit\nA test plan, participant count, anonymized observations, at least five findings with severity/impact, updated prototype, and retest results. Do not overgeneralize from a small sample.\n\n## 6. How to check your work\nDocument participant count, consent, and anonymous notes. Prioritize five observations; do not invent findings when evidence is limited—label hypotheses separately."},{"slug":"ui-ux-design","task_number":10,"title":"Final UX Case Study","old_description":"[[AZ]]\nAraşdırma, axın, ekran və test nəticələrini qərara yönəlmiş UX case study-də birləşdir.\n\n[[EN]]\nCombine research, flows, screens, and test results into a decision-oriented UX case study.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAraşdırmadan final dizayna qədər qərarları sübutlarla izah edən UX case study hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 materialların: araşdırma, user flow, wireframe, prototip, accessibility və usability nəticələri. Həqiqi tədqiqat yoxdursa, fərziyyəni açıq qeyd et.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylını və əvvəlki tapşırıq materiallarını davam etdir.\n2. Problemi, istifadəçi qrupunu və uğur ölçüsünü qısa yaz.\n3. Araşdırma tapıntısı → user flow → wireframe → final ekran əlaqəsini göstər.\n4. Usability test nəticələrini fərziyyələrlə müqayisə et; ölçülməyən uğuru uydurma.\n5. Accessibility və responsive qərarları, məlum məhdudiyyətləri və növbəti addımları izah et.\n6. Paylaşılan prototip linki, export və 5 dəqiqəlik təqdimat hazırla.\n\n## 4. Konkret nümunə və izah\nBir qərarın izini göstər: iştirakçı təhvil formatını tapa bilmədi → detail ekranında “Nə göndərməliyəm?” bloku əlavə edildi → təkrar sınaqda nəticə qeyd edildi. Sadəcə final screenshot-lar deyil, qərarın səbəbi də təqdim olunmalıdır.\n\n## 5. Nə təhvil verməlisən?\nCase study PDF və ya web linki, source design file, prototip, anonim test tapıntıları və 3 prioritet növbəti addım. Hər əsas dizayn qərarı istifadəçi ehtiyacı və ya test sübutu ilə əlaqələndirilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAraşdırma, axın, wireframe və final dizayn bir-birinə bağlıdır. Prototip linki açılır, 5 dəqiqəlik təqdimat hazırdır; üç növbəti iş sübutla prioritetləşdirilib.\n\n[[EN]]\n## 1. Goal\nCreate a UX case study that explains design decisions from research through the final design, supported by evidence.\n\n## 2. Before you start\nYour materials from Tasks 1–9: research, user flow, wireframes, prototype, accessibility, and usability findings. Clearly label assumptions if no real research was conducted.\n\n## 3. Step-by-step work\n1. Continue the same design file and earlier task artifacts.\n2. Briefly state the problem, target users, and success measure.\n3. Show the connection from research finding → user flow → wireframe → final screen.\n4. Compare usability-test results with assumptions; never invent unmeasured success.\n5. Explain accessibility/responsive decisions, known limitations, and next steps.\n6. Prepare a shareable prototype, an export, and a five-minute presentation.\n\n## 4. Concrete example and explanation\nTrace a decision: a participant could not find the submission format → add a What to submit block → record retest results. Explain decisions instead of showing only final screenshots.\n\n## 5. What to submit\nA case-study PDF or web link, source design file, prototype, anonymized test findings, and three prioritized next steps. Every major design decision must connect to a user need or test evidence.\n\n## 6. How to check your work\nConnect research, flow, wireframes, and final design. Provide an accessible prototype and five-minute presentation; prioritize three evidence-based next steps.","new_description":"[[AZ]]\nAraşdırma, axın, ekran və test nəticələrini qərara yönəlmiş UX case study-də birləşdir.\n\nPulsuz alətlər: Penpot (free/open source), Google Slides (personal), Google Docs (personal). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nCombine research, flows, screens, and test results into a decision-oriented UX case study.\n\nFree tools: Penpot (free/open source), Google Slides (personal), Google Docs (personal). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Problem → araşdırma → user flow → wireframe → test → yekun dizaynı 6 slayda topla.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Penpot (free/open source)** — https://penpot.app. Pulsuz planda frame, prototip və dizayn komponentləri hazırla; hesab limitlərini yoxla.\n- **Google Slides (personal)** — https://slides.google.com. Bir slaydda bir fikir saxla, export PDF al və mənbələri qeyd et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / ui-ux-design / task-10` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. İlkin məqsədi, vacib araşdırma nəticəsini və dizayn qərarlarını bağla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Real iştirakçı məlumatını sintetik ssenaridən ayrı qeyd et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Edit edilən dizayn linki, export PDF və əsas məhdudiyyətləri handoff-a əlavə et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Problem → araşdırma → user flow → wireframe → test → yekun dizaynı 6 slayda topla. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nProblem → araşdırma → user flow → wireframe → test → yekun dizaynı 6 slayda topla.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırığın tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nAraşdırmadan final dizayna qədər qərarları sübutlarla izah edən UX case study hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 materialların: araşdırma, user flow, wireframe, prototip, accessibility və usability nəticələri. Həqiqi tədqiqat yoxdursa, fərziyyəni açıq qeyd et.\n\n## 3. Addım-addım icra\n1. Eyni dizayn faylını və əvvəlki tapşırıq materiallarını davam etdir.\n2. Problemi, istifadəçi qrupunu və uğur ölçüsünü qısa yaz.\n3. Araşdırma tapıntısı → user flow → wireframe → final ekran əlaqəsini göstər.\n4. Usability test nəticələrini fərziyyələrlə müqayisə et; ölçülməyən uğuru uydurma.\n5. Accessibility və responsive qərarları, məlum məhdudiyyətləri və növbəti addımları izah et.\n6. Paylaşılan prototip linki, export və 5 dəqiqəlik təqdimat hazırla.\n\n## 4. Konkret nümunə və izah\nBir qərarın izini göstər: iştirakçı təhvil formatını tapa bilmədi → detail ekranında “Nə göndərməliyəm?” bloku əlavə edildi → təkrar sınaqda nəticə qeyd edildi. Sadəcə final screenshot-lar deyil, qərarın səbəbi də təqdim olunmalıdır.\n\n## 5. Nə təhvil verməlisən?\nCase study PDF və ya web linki, source design file, prototip, anonim test tapıntıları və 3 prioritet növbəti addım. Hər əsas dizayn qərarı istifadəçi ehtiyacı və ya test sübutu ilə əlaqələndirilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAraşdırma, axın, wireframe və final dizayn bir-birinə bağlıdır. Prototip linki açılır, 5 dəqiqəlik təqdimat hazırdır; üç növbəti iş sübutla prioritetləşdirilib.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Summarize problem, research, flow, wireframes, tests and final design in six slides.\n\n## Free platforms and how to use them\n- **Penpot (free/open source)** — https://penpot.app. Use free design boards, interactive prototypes and components within plan limits.\n- **Google Slides (personal)** — https://slides.google.com. Keep one idea per slide, cite sources and export to PDF.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / ui-ux-design / task-10` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Connect the initial problem to findings and key design decisions. Show evidence in a real screen, prototype, source file or test.\n4. Separate real observations from simulated cases. Show evidence in a real screen, prototype, source file or test.\n5. Provide editable design, exported PDF and known limitations. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Summarize problem, research, flow, wireframes, tests and final design in six slides. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nSummarize problem, research, flow, wireframes, tests and final design in six slides.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate a UX case study that explains design decisions from research through the final design, supported by evidence.\n\n## 2. Before you start\nYour materials from Tasks 1–9: research, user flow, wireframes, prototype, accessibility, and usability findings. Clearly label assumptions if no real research was conducted.\n\n## 3. Step-by-step work\n1. Continue the same design file and earlier task artifacts.\n2. Briefly state the problem, target users, and success measure.\n3. Show the connection from research finding → user flow → wireframe → final screen.\n4. Compare usability-test results with assumptions; never invent unmeasured success.\n5. Explain accessibility/responsive decisions, known limitations, and next steps.\n6. Prepare a shareable prototype, an export, and a five-minute presentation.\n\n## 4. Concrete example and explanation\nTrace a decision: a participant could not find the submission format → add a What to submit block → record retest results. Explain decisions instead of showing only final screenshots.\n\n## 5. What to submit\nA case-study PDF or web link, source design file, prototype, anonymized test findings, and three prioritized next steps. Every major design decision must connect to a user need or test evidence.\n\n## 6. How to check your work\nConnect research, flow, wireframes, and final design. Provide an accessible prototype and five-minute presentation; prioritize three evidence-based next steps."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='ui-ux-design' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Original version mismatch in ui-ux-design: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='ui-ux-design' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Only % tasks updated for ui-ux-design',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='ui-ux-design' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update mismatch in ui-ux-design: %',n; END IF;
END; $verify$;
COMMIT;
